function openCertModal(e,t,o){const s=document.getElementById("certModal"),i=document.getElementById("certModalImg"),n=document.getElementById("certModalTitle"),c=document.getElementById("certModalLink");i.src="",i.alt="Chargement...",n.textContent="Chargement en cours...";const d=new Image;d.src=e,d.onload=function(){i.src=e,i.alt=t,n.textContent=t,c.href=o,d.height>.7*window.innerHeight?(i.classList.add("max-h-[70vh]","w-auto"),i.classList.remove("max-w-full")):(i.classList.add("max-w-full"),i.classList.remove("max-h-[70vh]","w-auto")),s.classList.remove("invisible","opacity-0"),s.classList.add("visible","opacity-100"),document.body.classList.add("overflow-hidden")},d.onerror=function(){n.textContent="Erreur de chargement",i.src="",i.alt="Image non disponible",c.style.display="none",s.classList.remove("invisible","opacity-0"),s.classList.add("visible","opacity-100"),document.body.classList.add("overflow-hidden")}}document.getElementById("closeCertModal").onclick=function(){document.getElementById("certModal").classList.add("invisible","opacity-0"),document.getElementById("certModal").classList.remove("visible","opacity-100"),document.body.classList.remove("overflow-hidden")},document.getElementById("certModal").onclick=function(e){e.target===this&&(this.classList.add("invisible","opacity-0"),this.classList.remove("visible","opacity-100"),document.body.classList.remove("overflow-hidden"))},document.addEventListener("keydown",function(e){const t=document.getElementById("certModal");"Escape"===e.key&&t.classList.contains("visible")&&(t.classList.add("invisible","opacity-0"),t.classList.remove("visible","opacity-100"),document.body.classList.remove("overflow-hidden"))});